const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{pathToFileURL}=require('node:url');
const root=path.join(__dirname,'..');
async function load(){const url=pathToFileURL(path.join(root,'vendor/three.module.js')).href,T=await import(url),source=fs.readFileSync(path.join(root,'npc-animation.js'),'utf8').replace("from 'three'",`from '${url}'`);return {T,...await import('data:text/javascript;base64,'+Buffer.from(source).toString('base64'))};}
test('NPC deformation is per-instance, preserves root transforms, and leaves scenery untouched',async()=>{const {T,markNPC,animateNPCScene}=await load(),scene=new T.Scene(),template=new T.BoxGeometry(.5,1.8,.3,1,8,1),original=[...template.attributes.position.array],person=new T.Group(),mesh=new T.Mesh(template,new T.MeshStandardMaterial());mesh.position.y=.9;person.add(mesh);person.position.set(2,0,3);scene.add(person);const tree=new T.Mesh(template,new T.MeshStandardMaterial());scene.add(tree);markNPC(person,'working');animateNPCScene(scene,100);animateNPCScene(scene,200);assert.notEqual(mesh.geometry,template);assert.deepEqual([...template.attributes.position.array],original);assert.equal(tree.geometry,template);assert.deepEqual(person.position.toArray(),[2,0,3]);assert.ok([...mesh.geometry.attributes.position.array].every(Number.isFinite));assert.notDeepEqual([...mesh.geometry.attributes.position.array],original);});
test('pause freezes geometry and does not advance work; resume continues',async()=>{const {T,markNPC,animateNPCScene}=await load(),scene=new T.Scene(),person=new T.Group(),mesh=new T.Mesh(new T.BoxGeometry(.5,1.8,.3,1,8,1),new T.MeshStandardMaterial());person.add(mesh);scene.add(person);markNPC(person,'working');animateNPCScene(scene,100);person.userData.npcMotion.paused=true;const before=[...mesh.geometry.attributes.position.array];animateNPCScene(scene,300);assert.deepEqual([...mesh.geometry.attributes.position.array],before);person.userData.npcMotion.paused=false;animateNPCScene(scene,400);assert.notDeepEqual([...mesh.geometry.attributes.position.array],before);});
test('human allowlist excludes animals and buildings; clips follow activity',async()=>{const {isHumanAsset,motionKind}=await load();for(const id of ['daddy-idle','GF-008','BA-0087'])assert.ok(isHumanAsset(id));for(const id of ['marley-idle','horse-idle','GF-004','BA-0018','barn'])assert.ok(!isHumanAsset(id));assert.equal(motionKind('carrying harvest',true),'carry');assert.equal(motionKind('harvesting',false),'work');assert.equal(motionKind('resting',false),'idle');});
